"""MyDesk v303 適用（見積を実シート準拠に：業者カード折りたたみ／出来高=単価×単位・運搬費・処分費・諸経費・見積金額自動）
使い方: dashboard.jsx と同じフォルダで  python3 apply_v303_dashboard.py"""
import gzip, base64, json, sys, os
PATH="dashboard.jsx"
if not os.path.exists(PATH):
    print("❌ dashboard.jsx が見つかりません。同じフォルダで実行してください。"); sys.exit(1)
PAIRS=json.loads('[["H4sIADhQa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy1S0zNjDSLS7JL0rVzcwtyC8q0S1JzS3ISSxJVbJW0NdXeNw8+XHz6sfNnS/WznjasfTp2gkA23c2NFMAAAA=", "H4sIADhQa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1wWSZcYGxrqFpfklqbrJ+cUluklFqYnZKfnleUrWCvr6Co+bJz9uXv24ufPF2hlPO5Y+XTsBAHZRH0JSAAAA"], ["H4sIADhQa2oC/zWOsQ6DMAxEfyVlQIlEQ9eCYOvQuSOiEgIDkYxDkzAR/r1JUae7e2dZxxhj3MBHGrCrJgsSFYH1vmmFHLV5dP3Msap3pkaOaYpSOView6WiDVGw1agebPPHbbUv4GY9FChP432SZBspF0iUX+4WvZErXs4omjjKM8dKhCErdj3wvHnfrvc2n7JAM9IOwoco8ewo2SHKLzLuFKu9AAAA", "H4sIADhQa2oC/02NzQqDMAzHX6XzIAqjD6C42w57huGhaMRCTLWtg2F99zUVZZfk9/8gEUKIwsIiLbjZkAOJmsCF8G5LORj7VN1YYPPYhB4KzHOU2sP06m8NrYilmK3uwL1Pu222Cfxo+grlASFk2X0l7aPDK+nFf6OMMylvFcXnlisXp6TXkZ3CGJyY/AEVl3klbT5gR1D89cTkd4Z67bWhGFwcAkoyHlKDofrTajIr8e0D2NtrsZf1D93dO4kpAQAA"], ["", ""]]')
def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")
raw=open(PATH,"rb").read(); had_crlf=b"\r\n" in raw
text=raw.replace(b"\r\n",b"\n").decode("utf-8")
applied=skipped=0
for eo,en in PAIRS:
    old,new=dec(eo),dec(en)
    if text.count(new)>=1: skipped+=1; continue
    c=text.count(old)
    if c==0:
        print("❌ 対象が見つかりません（現在のビルドを確認）:"); print("   "+old[:80].replace("\n"," / ")); print("   grep MYDESK_BUILD dashboard.jsx"); sys.exit(1)
    if c!=1:
        print("❌ 対象が%d箇所（1箇所想定）"%c); sys.exit(1)
    text=text.replace(old,new,1); applied+=1
out=text.replace("\n","\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH,"wb").write(out)
print("✅ v303 適用完了 (適用 %d / スキップ %d)"%(applied,skipped))
print("   ビルド: 2026-07-26-v303-quote-cost-breakdown")
